    g.strokeStyle = "rgba(0,0,0,0.5)"; g.lineWidth = w + 1.4;
    g.beginPath(); g.moveTo(a[0], a[1]); g.lineTo(b[0], b[1]); g.stroke();
    g.strokeStyle = hex; g.lineWidth = w;
    g.beginPath(); g.moveTo(a[0], a[1]); g.lineTo(b[0], b[1]); g.stroke();
    g.strokeStyle = "rgba(0,0,0,0.55)"; g.lineWidth = 0.7;
