  // Lapel buttonholes are placed for the wearer's left lapel (viewer's right)
  // and mirrored across x = 401.5 for the other side.
  const MIRROR_X = 803;
  const mirrorPts = (pts) => pts.map((p) => [MIRROR_X - p[0], p[1]]);
