    if (db) return [LAPEL_PROFILES.dbR, LAPEL_PROFILES.dbL];
    const c = v.collar;
    const k = arc ? "arc" : /Peak/.test(c) ? "peak" : c === "Diamond Lapel" ? "diamond" : c === "Shawl" ? "shawl" : "notch";
